-- P0-1 MANUAL APPLY: idempotent MySQL/MariaDB production migration.
CREATE TABLE IF NOT EXISTS user_access_scopes (user_access_scope_id BIGINT NOT NULL AUTO_INCREMENT,user_id INT NOT NULL,scope_type ENUM('university','college','department','program','section') NOT NULL,scope_id INT NOT NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP NULL DEFAULT NULL,updated_at TIMESTAMP NULL DEFAULT NULL,PRIMARY KEY(user_access_scope_id),UNIQUE KEY user_scope_unique(user_id,scope_type,scope_id),KEY active_scope_lookup(scope_type,scope_id,is_active),CONSTRAINT fk_user_access_scopes_user FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DELIMITER //
DROP PROCEDURE IF EXISTS p01_guard//
CREATE PROCEDURE p01_guard()
BEGIN
 IF (SELECT COUNT(*) FROM users WHERE BINARY username=BINARY 'registrar')<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STOP: registrar identity missing or ambiguous'; END IF;
 IF (SELECT COUNT(*) FROM users WHERE BINARY username=BINARY 'exam.board')<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STOP: exam.board identity missing or ambiguous'; END IF;
 IF EXISTS(SELECT student_id FROM users WHERE student_id IS NOT NULL GROUP BY student_id HAVING COUNT(*)>1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STOP: duplicate student links'; END IF;
 IF EXISTS(SELECT employee_id FROM users WHERE employee_id IS NOT NULL GROUP BY employee_id HAVING COUNT(*)>1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STOP: duplicate employee links'; END IF;
 IF EXISTS(SELECT 1 FROM user_access_scopes s LEFT JOIN organizational_units root ON s.scope_type='university' AND root.organizational_unit_id=s.scope_id AND root.unit_code='PRES' LEFT JOIN colleges c ON s.scope_type='college' AND c.college_id=s.scope_id LEFT JOIN departments d ON s.scope_type='department' AND d.department_id=s.scope_id LEFT JOIN academic_programs ap ON s.scope_type='program' AND ap.academic_program_id=s.scope_id LEFT JOIN course_offerings co ON s.scope_type='section' AND co.course_offering_id=s.scope_id WHERE CASE s.scope_type WHEN 'university' THEN root.organizational_unit_id WHEN 'college' THEN c.college_id WHEN 'department' THEN d.department_id WHEN 'program' THEN ap.academic_program_id WHEN 'section' THEN co.course_offering_id END IS NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STOP: orphan access scope requires resolution'; END IF;
 IF (SELECT COUNT(*) FROM organizational_unit_types WHERE type_code='administration' AND is_active=1)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STOP: active unit type administration missing or ambiguous'; END IF;
 IF (SELECT COUNT(*) FROM organizational_unit_types WHERE type_code='center' AND is_active=1)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STOP: active unit type center missing or ambiguous'; END IF;
 IF (SELECT COUNT(*) FROM organizational_unit_types WHERE type_code='club' AND is_active=1)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STOP: active unit type club missing or ambiguous'; END IF;
 IF (SELECT COUNT(*) FROM organizational_unit_types WHERE type_code='college' AND is_active=1)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STOP: active unit type college missing or ambiguous'; END IF;
 IF (SELECT COUNT(*) FROM organizational_unit_types WHERE type_code='directorate' AND is_active=1)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STOP: active unit type directorate missing or ambiguous'; END IF;
 IF (SELECT COUNT(*) FROM organizational_unit_types WHERE type_code='institute' AND is_active=1)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STOP: active unit type institute missing or ambiguous'; END IF;
 IF (SELECT COUNT(*) FROM organizational_unit_types WHERE type_code='lab' AND is_active=1)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STOP: active unit type lab missing or ambiguous'; END IF;
 IF (SELECT COUNT(*) FROM organizational_unit_types WHERE type_code='office' AND is_active=1)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STOP: active unit type office missing or ambiguous'; END IF;
 IF (SELECT COUNT(*) FROM organizational_unit_types WHERE type_code='presidency' AND is_active=1)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STOP: active unit type presidency missing or ambiguous'; END IF;
 IF (SELECT COUNT(*) FROM organizational_unit_types WHERE type_code='unit' AND is_active=1)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STOP: active unit type unit missing or ambiguous'; END IF;
 IF (SELECT COUNT(*) FROM organizational_unit_types WHERE type_code='vice_presidency' AND is_active=1)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STOP: active unit type vice_presidency missing or ambiguous'; END IF;
 IF (SELECT COUNT(*) FROM employee_types WHERE type_code='administrative' AND is_active=1)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STOP: administrative employee type missing'; END IF;
 IF (SELECT COUNT(*) FROM employee_statuses WHERE status_code='active' AND is_active=1)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STOP: active employee status missing'; END IF;
 IF (SELECT COUNT(*) FROM roles WHERE role_code IN ('board_member','registration_officer','doctor_instructor','student') AND is_active=1)<>4 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STOP: required roles missing'; END IF;
 IF (SELECT COUNT(*) FROM permissions WHERE permission_code IN ('academic_structure.view','admissions.manage','admissions.view','attendance.manage','attendance.view','courses.view','exams.manage','exams.view','grades.manage','grades.view','registration.manage','registration.view','students.manage','students.view','system_settings.view') AND is_active=1)<>15 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STOP: required permissions missing'; END IF;
END//
CALL p01_guard()//
DROP PROCEDURE p01_guard//
DELIMITER ;
START TRANSACTION;
-- Deterministic staff rows are created only for the two unlinked P0-1 identities. Existing employees are never repurposed.
UPDATE users u JOIN employees e ON e.employee_number=CASE u.username WHEN 'registrar' THEN 'P01-REGISTRAR' WHEN 'exam.board' THEN 'P01-EXAM-BOARD' END SET u.employee_id=e.employee_id WHERE u.username IN ('registrar','exam.board') AND u.employee_id IS NULL;
UPDATE employees e JOIN users u ON u.employee_id=e.employee_id JOIN organizational_units ou ON ou.unit_code=CASE u.username WHEN 'registrar' THEN '732' WHEN 'exam.board' THEN '735' END SET e.organizational_unit_id=ou.organizational_unit_id WHERE u.username IN ('registrar','exam.board');
UPDATE user_roles ur JOIN users u ON u.user_id=ur.user_id JOIN roles r ON r.role_id=ur.role_id SET ur.is_active=1 WHERE (u.username='registrar' AND r.role_code='registration_officer') OR (u.username='exam.board' AND r.role_code='board_member');
DROP TEMPORARY TABLE IF EXISTS p01_required_permissions;
CREATE TEMPORARY TABLE p01_required_permissions(role_code VARCHAR(80),permission_code VARCHAR(120),PRIMARY KEY(role_code,permission_code));
-- Insert only missing required grants: unrelated/custom grants are deliberately preserved.
DROP TEMPORARY TABLE p01_required_permissions;
COMMIT;
