INSERT INTO employees(employee_number,first_name,last_name,email,employee_type_id,employee_status_id,organizational_unit_id,created_at,updated_at) SELECT 'P01-REGISTRAR','P0-1','Registrar',u.email,et.employee_type_id,es.employee_status_id,ou.organizational_unit_id,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM users u JOIN employee_types et ON et.type_code='administrative' JOIN employee_statuses es ON es.status_code='active' JOIN organizational_units ou ON ou.unit_code='732' WHERE u.username='registrar' AND u.employee_id IS NULL AND NOT EXISTS(SELECT 1 FROM employees WHERE employee_number='P01-REGISTRAR');
INSERT INTO employees(employee_number,first_name,last_name,email,employee_type_id,employee_status_id,organizational_unit_id,created_at,updated_at) SELECT 'P01-EXAM-BOARD','P0-1','Exam Board',u.email,et.employee_type_id,es.employee_status_id,ou.organizational_unit_id,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM users u JOIN employee_types et ON et.type_code='administrative' JOIN employee_statuses es ON es.status_code='active' JOIN organizational_units ou ON ou.unit_code='735' WHERE u.username='exam.board' AND u.employee_id IS NULL AND NOT EXISTS(SELECT 1 FROM employees WHERE employee_number='P01-EXAM-BOARD');
INSERT INTO user_roles(user_id,role_id,assigned_at,is_active) SELECT u.user_id,r.role_id,CURRENT_TIMESTAMP,1 FROM users u JOIN roles r ON r.role_code=CASE u.username WHEN 'registrar' THEN 'registration_officer' WHEN 'exam.board' THEN 'board_member' END WHERE u.username IN ('registrar','exam.board') AND NOT EXISTS(SELECT 1 FROM user_roles ur WHERE ur.user_id=u.user_id AND ur.role_id=r.role_id);
