INSERT INTO role_permissions(role_id,permission_id,granted_at) SELECT r.role_id,p.permission_id,CURRENT_TIMESTAMP FROM p01_required_permissions x JOIN roles r ON r.role_code=x.role_code JOIN permissions p ON p.permission_code=x.permission_code LEFT JOIN role_permissions rp ON rp.role_id=r.role_id AND rp.permission_id=p.permission_id WHERE rp.role_permission_id IS NULL;
INSERT INTO user_access_scopes(user_id,scope_type,scope_id,is_active,created_at,updated_at) SELECT u.user_id,'university',p.organizational_unit_id,1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM users u JOIN organizational_units p ON p.unit_code='PRES' WHERE u.username IN ('registrar','exam.board') ON DUPLICATE KEY UPDATE is_active=1,updated_at=CURRENT_TIMESTAMP;
